INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00001', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 0, 'The HCF of two numbers is 4 and their LCM is 24. If one of the numbers is 8, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

So the other number is `(HCF × LCM) / A = (4 × 24) / 8 = 12`.

The answer is **12**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00002', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 1, 'The HCF of two numbers is 6 and their LCM is 72. If one of the numbers is 18, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

So the other number is `(HCF × LCM) / A = (6 × 72) / 18 = 24`.

The answer is **24**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00003', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 2, 'The HCF of two numbers is 7 and their LCM is 105. If one of the numbers is 21, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

