INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00004', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 3, 'The HCF of two numbers is 8 and their LCM is 160. If one of the numbers is 32, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

