INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00005', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 4, 'The HCF of two numbers is 9 and their LCM is 270. If one of the numbers is 45, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

So the other number is `(HCF × LCM) / A = (9 × 270) / 45 = 54`.

The answer is **54**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00006', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 5, 'The HCF of two numbers is 10 and their LCM is 100. If one of the numbers is 20, find the other number.', 'For any two numbers, the product of the numbers is equal to the product of their HCF and LCM: `Product = HCF × LCM`.

So the other number is `(HCF × LCM) / A = (10 × 100) / 20 = 50`.

The answer is **50**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00007', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 6, 'Find the HCF and LCM of 18 and 24.', 'Using the Euclidean algorithm, repeatedly divide the larger number by the smaller and replace it with the remainder until the remainder is 0; the last non-zero remainder is the HCF.

This gives `HCF(18, 24) = 6`. Since `LCM × HCF = a × b`, we get `LCM = (18 × 24) / 6 = 72`.

The answer is **HCF = 6 and LCM = 72**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00008', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 7, 'Find the HCF and LCM of 28 and 42.', 'Using the Euclidean algorithm, repeatedly divide the larger number by the smaller and replace it with the remainder until the remainder is 0; the last non-zero remainder is the HCF.

This gives `HCF(28, 42) = 14`. Since `LCM × HCF = a × b`, we get `LCM = (28 × 42) / 14 = 84`.

The answer is **HCF = 14 and LCM = 84**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00009', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 8, 'Find the HCF and LCM of 36 and 60.', 'Using the Euclidean algorithm, repeatedly divide the larger number by the smaller and replace it with the remainder until the remainder is 0; the last non-zero remainder is the HCF.

This gives `HCF(36, 60) = 12`. Since `LCM × HCF = a × b`, we get `LCM = (36 × 60) / 12 = 180`.

The answer is **HCF = 12 and LCM = 180**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00010', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 9, 'Find the HCF and LCM of 45 and 75.', 'Using the Euclidean algorithm, repeatedly divide the larger number by the smaller and replace it with the remainder until the remainder is 0; the last non-zero remainder is the HCF.

This gives `HCF(45, 75) = 15`. Since `LCM × HCF = a × b`, we get `LCM = (45 × 75) / 15 = 225`.

The answer is **HCF = 15 and LCM = 225**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00011', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 10, 'Find the HCF and LCM of 16 and 40.', 'Using the Euclidean algorithm, repeatedly divide the larger number by the smaller and replace it with the remainder until the remainder is 0; the last non-zero remainder is the HCF.

This gives `HCF(16, 40) = 8`. Since `LCM × HCF = a × b`, we get `LCM = (16 × 40) / 8 = 80`.

The answer is **HCF = 8 and LCM = 80**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00012', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 11, 'Find the smallest number which, when divided by 6, 8 and 12, leaves a remainder of 3 in each case.', 'A number that leaves the same remainder `r` when divided by several divisors is of the form `LCM(divisors) × k + r`, and the smallest such number occurs at `k = 1`.

`LCM(6, 8, 12) = 24`, so the smallest number is `24 + 3 = 27`.

The answer is **27**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00013', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 12, 'Find the smallest number which, when divided by 5, 6 and 9, leaves a remainder of 2 in each case.', 'A number that leaves the same remainder `r` when divided by several divisors is of the form `LCM(divisors) × k + r`, and the smallest such number occurs at `k = 1`.

`LCM(5, 6, 9) = 90`, so the smallest number is `90 + 2 = 92`.

The answer is **92**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00014', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 13, 'Find the smallest number which, when divided by 4, 7 and 10, leaves a remainder of 3 in each case.', 'A number that leaves the same remainder `r` when divided by several divisors is of the form `LCM(divisors) × k + r`, and the smallest such number occurs at `k = 1`.

`LCM(4, 7, 10) = 140`, so the smallest number is `140 + 3 = 143`.

The answer is **143**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00015', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 14, 'Find the smallest number which, when divided by 8, 12 and 16, leaves a remainder of 5 in each case.', 'A number that leaves the same remainder `r` when divided by several divisors is of the form `LCM(divisors) × k + r`, and the smallest such number occurs at `k = 1`.

