INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00016', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 15, 'Find the smallest number which, when divided by 6, 10 and 15, leaves a remainder of 4 in each case.', 'A number that leaves the same remainder `r` when divided by several divisors is of the form `LCM(divisors) × k + r`, and the smallest such number occurs at `k = 1`.

`LCM(6, 10, 15) = 30`, so the smallest number is `30 + 4 = 34`.

