INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00017', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 16, 'What is the smallest number that must be added to 1234 so that the result is exactly divisible by 15?', 'Divide 1234 by 15 and find the remainder: `1234 mod 15 = 4`.

The number to be added is `15 - 4 = 11` (since adding this makes the sum a multiple of 15).

The answer is **11**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00018', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 17, 'What is the smallest number that must be added to 2789 so that the result is exactly divisible by 23?', 'Divide 2789 by 23 and find the remainder: `2789 mod 23 = 6`.

