INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00019', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 18, 'What is the smallest number that must be added to 5678 so that the result is exactly divisible by 34?', 'Divide 5678 by 34 and find the remainder: `5678 mod 34 = 0`.

