INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00020', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 19, 'What is the smallest number that must be added to 9876 so that the result is exactly divisible by 27?', 'Divide 9876 by 27 and find the remainder: `9876 mod 27 = 21`.

