INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00022', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 21, 'Find the sum of the first 45 natural numbers.', 'The sum of the first `n` natural numbers is given by `n(n+1)/2`.

