INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00032', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 31, 'Find the sum of the cubes of the first 8 natural numbers.', 'The sum of the cubes of the first `n` natural numbers equals the square of the sum of the first `n` natural numbers: `[n(n+1)/2]^2`.

Substituting `n = 8`: the sum of the first 8 natural numbers is `8 × 9 / 2 = 36`, so the sum of cubes is `36^2 = 1296`.

