INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00033', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 32, 'Find the sum of the cubes of the first 10 natural numbers.', 'The sum of the cubes of the first `n` natural numbers equals the square of the sum of the first `n` natural numbers: `[n(n+1)/2]^2`.

