INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00037', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 36, 'Find the average of 5 consecutive integers starting from 7.', 'For consecutive integers, the average equals the average of the first and last terms: `first + (n-1)/2`, since the last term is `a + (n-1)`.

