INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00042', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 41, 'Simplify using the BODMAS rule: `12 + 8 × 3 - 6 ÷ 2`.', 'Apply BODMAS: first resolve brackets, then division/multiplication (left to right), then addition/subtraction (left to right).

