INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00047', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 46, 'Using the divisibility rule for 11, determine whether 30514 is divisible by 11.', 'The rule for 11: find the difference between the sum of digits at odd positions (from the right) and the sum of digits at even positions; the number is divisible by 11 if this difference is 0 or a multiple of 11.

For 30514, the odd-position digit sum is `12` and the even-position digit sum is `1`, giving a difference of `12 - 1 = 11`.

The answer is **30514 is divisible by 11, since the difference 11 is a multiple of 11**.', '2026-11-14T06:17:56.365Z');
