INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00052', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 51, 'The sum of the digits of a two-digit number is 10. The number exceeds the number formed by reversing its digits by 18. Find the original number.', 'Let the tens digit be `a` and the units digit be `b`, so the number is `10a + b` and the reversed number is `10b + a`.

Given `a + b = 10` and `(10a+b) - (10b+a) = 9(a-b) = 18`, so `a - b = 18/9 = 2`. Solving the two equations, `a = (10+2)/2 = 6` and `b = (10-2)/2 = 4`.

The answer is **the number is 64**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00053', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 52, 'The sum of the digits of a two-digit number is 12. The number exceeds the number formed by reversing its digits by 36. Find the original number.', 'Let the tens digit be `a` and the units digit be `b`, so the number is `10a + b` and the reversed number is `10b + a`.

Given `a + b = 12` and `(10a+b) - (10b+a) = 9(a-b) = 36`, so `a - b = 36/9 = 4`. Solving the two equations, `a = (12+4)/2 = 8` and `b = (12-4)/2 = 4`.

The answer is **the number is 84**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00054', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 53, 'The sum of the digits of a two-digit number is 14. The number exceeds the number formed by reversing its digits by 18. Find the original number.', 'Let the tens digit be `a` and the units digit be `b`, so the number is `10a + b` and the reversed number is `10b + a`.

Given `a + b = 14` and `(10a+b) - (10b+a) = 9(a-b) = 18`, so `a - b = 18/9 = 2`. Solving the two equations, `a = (14+2)/2 = 8` and `b = (14-2)/2 = 6`.

The answer is **the number is 86**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00055', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 54, 'The sum of the digits of a two-digit number is 8. The number exceeds the number formed by reversing its digits by 36. Find the original number.', 'Let the tens digit be `a` and the units digit be `b`, so the number is `10a + b` and the reversed number is `10b + a`.

Given `a + b = 8` and `(10a+b) - (10b+a) = 9(a-b) = 36`, so `a - b = 36/9 = 4`. Solving the two equations, `a = (8+4)/2 = 6` and `b = (8-4)/2 = 2`.

The answer is **the number is 62**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00056', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 55, 'The sum of the digits of a two-digit number is 11. The number exceeds the number formed by reversing its digits by 27. Find the original number.', 'Let the tens digit be `a` and the units digit be `b`, so the number is `10a + b` and the reversed number is `10b + a`.

Given `a + b = 11` and `(10a+b) - (10b+a) = 9(a-b) = 27`, so `a - b = 27/9 = 3`. Solving the two equations, `a = (11+3)/2 = 7` and `b = (11-3)/2 = 4`.

The answer is **the number is 74**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00057', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 56, 'Find the largest 3-digit number that is exactly divisible by 17.', 'The largest 3-digit number is `10^3 - 1 = 999`.

Dividing by 17, the remainder is `999 mod 17 = 13`, so subtract this remainder: `999 - 13 = 986`.

The answer is **986**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00058', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 57, 'Find the largest 4-digit number that is exactly divisible by 23.', 'The largest 4-digit number is `10^4 - 1 = 9999`.

