INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00062', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 61, 'The sum of two numbers is 42 and their difference is 8. Find the product of the two numbers.', 'If the numbers are `x` and `y` with `x + y = 42` and `x - y = 8`, then `x = (42+8)/2` and `y = (42-8)/2`.

This gives `x = 25` and `y = 17`, so the product is `25 × 17 = 425`.

The answer is **425**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00063', 'math-aptitude-bank-2', 'Arithmetic & Number Systems', 0, 62, 'The sum of two numbers is 56 and their difference is 12. Find the product of the two numbers.', 'If the numbers are `x` and `y` with `x + y = 56` and `x - y = 12`, then `x = (56+12)/2` and `y = (56-12)/2`.

