INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00083', 'math-aptitude-bank-2', 'Percentages, Profit & Loss, and Interest', 1, 16, 'A value undergoes an increase of 20% followed by an increase of 10%. Find the net percentage change.', 'For two successive percentage changes `p1` and `p2`, the net change factor is `(1 + p1/100)(1 + p2/100)`.

`(1 + 20/100)(1 + 10/100) = 1.32`, so the net percentage change is `(1.32 - 1) × 100 = 32%`.

The answer is **a net increase of 32%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00084', 'math-aptitude-bank-2', 'Percentages, Profit & Loss, and Interest', 1, 17, 'A value undergoes an increase of 25% followed by a decrease of 20%. Find the net percentage change.', 'For two successive percentage changes `p1` and `p2`, the net change factor is `(1 + p1/100)(1 + p2/100)`.

`(1 + 25/100)(1 + -20/100) = 1`, so the net percentage change is `(1 - 1) × 100 = 0%`.

The answer is **a net increase of 0%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00085', 'math-aptitude-bank-2', 'Percentages, Profit & Loss, and Interest', 1, 18, 'A value undergoes an increase of 30% followed by a decrease of 10%. Find the net percentage change.', 'For two successive percentage changes `p1` and `p2`, the net change factor is `(1 + p1/100)(1 + p2/100)`.

