INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00088', 'math-aptitude-bank-2', 'Percentages, Profit & Loss, and Interest', 1, 21, 'An article is bought for ₹800 and sold for ₹920. Find the profit percentage.', 'Profit is `SP - CP` (or `CP - SP` for a loss), and the percentage is `(Profit / CP) × 100`.

