INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00108', 'math-aptitude-bank-2', 'Percentages, Profit & Loss, and Interest', 1, 41, 'A trader wants to earn a profit of 25% on an article costing ₹800, after allowing a discount of 20% on the marked price. Find the marked price.', 'The marked price must satisfy `MP × (1 - discount/100) = CP × (1 + profit/100)`, so `MP = CP × (1 + profit/100) / (1 - discount/100)`.

