INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00133', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 0, 'Divide ₹2400 among A, B and C in the ratio 2:3:5. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

The sum of parts is `2+3+5 = 10`, so A gets `2400 × 2/10 = ₹480`, B gets `2400 × 3/10 = ₹720`, and C gets `2400 × 5/10 = ₹1200`.

The answer is **A = ₹480, B = ₹720, C = ₹1200**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00134', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 1, 'Divide ₹3600 among A, B and C in the ratio 1:2:3. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

The sum of parts is `1+2+3 = 6`, so A gets `3600 × 1/6 = ₹600`, B gets `3600 × 2/6 = ₹1200`, and C gets `3600 × 3/6 = ₹1800`.

The answer is **A = ₹600, B = ₹1200, C = ₹1800**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00135', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 2, 'Divide ₹4500 among A, B and C in the ratio 3:4:5. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

