INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00136', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 3, 'Divide ₹6000 among A, B and C in the ratio 2:3:7. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

The sum of parts is `2+3+7 = 12`, so A gets `6000 × 2/12 = ₹1000`, B gets `6000 × 3/12 = ₹1500`, and C gets `6000 × 7/12 = ₹3500`.

The answer is **A = ₹1000, B = ₹1500, C = ₹3500**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00137', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 4, 'Divide ₹5400 among A, B and C in the ratio 1:3:5. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

The sum of parts is `1+3+5 = 9`, so A gets `5400 × 1/9 = ₹600`, B gets `5400 × 3/9 = ₹1800`, and C gets `5400 × 5/9 = ₹3000`.

The answer is **A = ₹600, B = ₹1800, C = ₹3000**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00138', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 5, 'Divide ₹7200 among A, B and C in the ratio 3:5:4. Find each person''s share.', 'When an amount is divided in the ratio `a:b:c`, each share is `Total × (part / sum of parts)`.

The sum of parts is `3+5+4 = 12`, so A gets `7200 × 3/12 = ₹1800`, B gets `7200 × 5/12 = ₹3000`, and C gets `7200 × 4/12 = ₹2400`.

The answer is **A = ₹1800, B = ₹3000, C = ₹2400**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00139', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 6, 'If A:B = 2:3 and B:C = 4:5, find A:B:C.', 'To combine the ratios, make the common term (B) equal in both by scaling: multiply the first ratio by 4 and the second ratio by 3.

This gives `A:B = 8:12` and `B:C = 12:15`, so `A:B:C = 8:12:15`, which simplifies to `8:12:15`.

The answer is **A:B:C = 8:12:15**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00140', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 7, 'If A:B = 3:4 and B:C = 2:5, find A:B:C.', 'To combine the ratios, make the common term (B) equal in both by scaling: multiply the first ratio by 2 and the second ratio by 4.

This gives `A:B = 6:8` and `B:C = 8:20`, so `A:B:C = 6:8:20`, which simplifies to `3:4:10`.

The answer is **A:B:C = 3:4:10**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00141', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 8, 'If A:B = 4:5 and B:C = 3:7, find A:B:C.', 'To combine the ratios, make the common term (B) equal in both by scaling: multiply the first ratio by 3 and the second ratio by 5.

This gives `A:B = 12:15` and `B:C = 15:35`, so `A:B:C = 12:15:35`, which simplifies to `12:15:35`.

The answer is **A:B:C = 12:15:35**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00142', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 9, 'If A:B = 5:6 and B:C = 2:3, find A:B:C.', 'To combine the ratios, make the common term (B) equal in both by scaling: multiply the first ratio by 2 and the second ratio by 6.

This gives `A:B = 10:12` and `B:C = 12:18`, so `A:B:C = 10:12:18`, which simplifies to `5:6:9`.

The answer is **A:B:C = 5:6:9**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00143', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 10, 'If A:B = 3:5 and B:C = 4:7, find A:B:C.', 'To combine the ratios, make the common term (B) equal in both by scaling: multiply the first ratio by 4 and the second ratio by 5.

This gives `A:B = 12:20` and `B:C = 20:35`, so `A:B:C = 12:20:35`, which simplifies to `12:20:35`.

The answer is **A:B:C = 12:20:35**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00144', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 11, 'Find the average of the numbers 45, 62, 78, 34, 91.', 'The average of a set of numbers is the sum of the numbers divided by how many there are.

The sum is `45 + 62 + 78 + 34 + 91 = 310`, and there are 5 numbers, so the average is `310 / 5 = 62`.

The answer is **62**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00145', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 12, 'Find the average of the numbers 23, 56, 89, 12, 45, 67.', 'The average of a set of numbers is the sum of the numbers divided by how many there are.

The sum is `23 + 56 + 89 + 12 + 45 + 67 = 292`, and there are 6 numbers, so the average is `292 / 6 = 48.67`.

The answer is **48.67**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00146', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 13, 'Find the average of the numbers 34, 45, 56, 67, 78.', 'The average of a set of numbers is the sum of the numbers divided by how many there are.

