INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00147', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 14, 'Find the average of the numbers 12, 24, 36, 48, 60, 72.', 'The average of a set of numbers is the sum of the numbers divided by how many there are.

The sum is `12 + 24 + 36 + 48 + 60 + 72 = 252`, and there are 6 numbers, so the average is `252 / 6 = 42`.

