INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00148', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 15, 'Find the average of the numbers 55, 65, 75, 85, 95.', 'The average of a set of numbers is the sum of the numbers divided by how many there are.

The sum is `55 + 65 + 75 + 85 + 95 = 375`, and there are 5 numbers, so the average is `375 / 5 = 75`.

The answer is **75**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00149', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 16, 'The average of 8 numbers is 42. When one more number is added, the average becomes 43. Find the number that was added.', 'The total of the original 8 numbers is `8 × 42`, and the total after adding the new number is `(8+1) × 43`.

The new number is the difference: `(9) × 43 - 8 × 42 = 387 - 336 = 51`.

The answer is **51**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00150', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 17, 'The average of 10 numbers is 55. When one more number is added, the average becomes 56. Find the number that was added.', 'The total of the original 10 numbers is `10 × 55`, and the total after adding the new number is `(10+1) × 56`.

The new number is the difference: `(11) × 56 - 10 × 55 = 616 - 550 = 66`.

The answer is **66**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00151', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 18, 'The average of 12 numbers is 38. When one more number is added, the average becomes 39.5. Find the number that was added.', 'The total of the original 12 numbers is `12 × 38`, and the total after adding the new number is `(12+1) × 39.5`.

The new number is the difference: `(13) × 39.5 - 12 × 38 = 513.5 - 456 = 57.5`.

The answer is **57.5**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00152', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 19, 'The average of 15 numbers is 60. When one more number is added, the average becomes 61. Find the number that was added.', 'The total of the original 15 numbers is `15 × 60`, and the total after adding the new number is `(15+1) × 61`.

The new number is the difference: `(16) × 61 - 15 × 60 = 976 - 900 = 76`.

The answer is **76**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00153', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 20, 'The average of 6 numbers is 50. When one more number is added, the average becomes 52. Find the number that was added.', 'The total of the original 6 numbers is `6 × 50`, and the total after adding the new number is `(6+1) × 52`.

The new number is the difference: `(7) × 52 - 6 × 50 = 364 - 300 = 64`.

The answer is **64**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00154', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 21, 'The average age of 10 people in a group is increased by 2 years when a person aged 25 years is replaced by a new person. Find the age of the new person.', 'When one member is replaced and the average changes by `d`, the total changes by `n × d`, so the new person''s value is `old value + n × d`.

New person''s age `= 25 + 10 × 2 = 45` years.

The answer is **45 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00155', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 22, 'The average age of 15 people in a group is increased by 3 years when a person aged 20 years is replaced by a new person. Find the age of the new person.', 'When one member is replaced and the average changes by `d`, the total changes by `n × d`, so the new person''s value is `old value + n × d`.

