INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00159', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 26, 'In what ratio must a 10% solution be mixed with a 40% solution to obtain a mixture that is 25% concentrated?', 'By the rule of alligation, the ratio of the two solutions is `(c2 - cm) : (cm - c1)`, where `cm` is the mean (mixture) concentration.

This gives the ratio `(40 - 25) : (25 - 10) = 15 : 15`, which simplifies to `1:1`.

The answer is **1:1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00160', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 27, 'In what ratio must a 20% solution be mixed with a 60% solution to obtain a mixture that is 35% concentrated?', 'By the rule of alligation, the ratio of the two solutions is `(c2 - cm) : (cm - c1)`, where `cm` is the mean (mixture) concentration.

This gives the ratio `(60 - 35) : (35 - 20) = 25 : 15`, which simplifies to `5:3`.

The answer is **5:3**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00161', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 28, 'In what ratio must a 15% solution be mixed with a 45% solution to obtain a mixture that is 30% concentrated?', 'By the rule of alligation, the ratio of the two solutions is `(c2 - cm) : (cm - c1)`, where `cm` is the mean (mixture) concentration.

