INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00163', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 30, 'In what ratio must a 25% solution be mixed with a 65% solution to obtain a mixture that is 45% concentrated?', 'By the rule of alligation, the ratio of the two solutions is `(c2 - cm) : (cm - c1)`, where `cm` is the mean (mixture) concentration.

