INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00164', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 31, 'A vessel contains 80 litres of milk. Each time, 1/4 of the mixture is removed and replaced with water, and this is done 2 times. Find the quantity of milk left in the vessel.', 'When a fraction `f` of a mixture is removed and replaced with water each time, after `n` operations the remaining original quantity is `Initial × (1 - f)^n`.

Here `f = 1/4`, so the milk remaining is `80 × (1 - 1/4)^2 = 80 × (0.75)^2 = 45` litres.

The answer is **45 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00165', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 32, 'A vessel contains 100 litres of milk. Each time, 1/5 of the mixture is removed and replaced with water, and this is done 3 times. Find the quantity of milk left in the vessel.', 'When a fraction `f` of a mixture is removed and replaced with water each time, after `n` operations the remaining original quantity is `Initial × (1 - f)^n`.

Here `f = 1/5`, so the milk remaining is `100 × (1 - 1/5)^3 = 100 × (0.8)^3 = 51.2` litres.

The answer is **51.2 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00166', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 33, 'A vessel contains 64 litres of milk. Each time, 1/8 of the mixture is removed and replaced with water, and this is done 2 times. Find the quantity of milk left in the vessel.', 'When a fraction `f` of a mixture is removed and replaced with water each time, after `n` operations the remaining original quantity is `Initial × (1 - f)^n`.

Here `f = 1/8`, so the milk remaining is `64 × (1 - 1/8)^2 = 64 × (0.88)^2 = 49` litres.

The answer is **49 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00167', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 34, 'A vessel contains 128 litres of milk. Each time, 1/4 of the mixture is removed and replaced with water, and this is done 3 times. Find the quantity of milk left in the vessel.', 'When a fraction `f` of a mixture is removed and replaced with water each time, after `n` operations the remaining original quantity is `Initial × (1 - f)^n`.

Here `f = 1/4`, so the milk remaining is `128 × (1 - 1/4)^3 = 128 × (0.75)^3 = 54` litres.

