INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00168', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 35, 'A vessel contains 243 litres of milk. Each time, 1/3 of the mixture is removed and replaced with water, and this is done 4 times. Find the quantity of milk left in the vessel.', 'When a fraction `f` of a mixture is removed and replaced with water each time, after `n` operations the remaining original quantity is `Initial × (1 - f)^n`.

Here `f = 1/3`, so the milk remaining is `243 × (1 - 1/3)^4 = 243 × (0.67)^4 = 48` litres.

The answer is **48 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00169', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 36, 'The present ages of two friends are in the ratio 4:5. After 8 years, the ratio of their ages will be 6:7. Find their present ages.', 'Let the present ages be `4k` and `5k`. After 8 years, `(4k + 8) / (5k + 8) = 6/7`.

Cross-multiplying and solving gives `k = 4`, so the present ages are `4 × 4 = 16` and `5 × 4 = 20` years.

The answer is **16 years and 20 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00170', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 37, 'The present ages of two friends are in the ratio 3:4. After 5 years, the ratio of their ages will be 4:5. Find their present ages.', 'Let the present ages be `3k` and `4k`. After 5 years, `(3k + 5) / (4k + 5) = 4/5`.

Cross-multiplying and solving gives `k = 5`, so the present ages are `3 × 5 = 15` and `4 × 5 = 20` years.

The answer is **15 years and 20 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00171', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 38, 'The present ages of two friends are in the ratio 5:6. After 4 years, the ratio of their ages will be 7:8. Find their present ages.', 'Let the present ages be `5k` and `6k`. After 4 years, `(5k + 4) / (6k + 4) = 7/8`.

Cross-multiplying and solving gives `k = 2`, so the present ages are `5 × 2 = 10` and `6 × 2 = 12` years.

The answer is **10 years and 12 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00172', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 39, 'The present ages of two friends are in the ratio 2:3. After 10 years, the ratio of their ages will be 3:4. Find their present ages.', 'Let the present ages be `2k` and `3k`. After 10 years, `(2k + 10) / (3k + 10) = 3/4`.

Cross-multiplying and solving gives `k = 10`, so the present ages are `2 × 10 = 20` and `3 × 10 = 30` years.

The answer is **20 years and 30 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00173', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 40, 'The present ages of two friends are in the ratio 7:8. After 6 years, the ratio of their ages will be 8:9. Find their present ages.', 'Let the present ages be `7k` and `8k`. After 6 years, `(7k + 6) / (8k + 6) = 8/9`.

Cross-multiplying and solving gives `k = 6`, so the present ages are `7 × 6 = 42` and `8 × 6 = 48` years.

The answer is **42 years and 48 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00174', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 41, 'In a class, 30 students scored an average of 65 marks and the other 70 students scored an average of 80 marks. Find the combined average of the whole class.', 'The combined average is the total marks of all students divided by the total number of students: `(n1 × m1 + n2 × m2) / (n1 + n2)`.

`(30 × 65 + 70 × 80) / (30 + 70) = 7550 / 100 = 75.5`.

The answer is **75.5**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00175', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 42, 'In a class, 25 students scored an average of 60 marks and the other 35 students scored an average of 72 marks. Find the combined average of the whole class.', 'The combined average is the total marks of all students divided by the total number of students: `(n1 × m1 + n2 × m2) / (n1 + n2)`.

