INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00176', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 43, 'In a class, 40 students scored an average of 55 marks and the other 20 students scored an average of 75 marks. Find the combined average of the whole class.', 'The combined average is the total marks of all students divided by the total number of students: `(n1 × m1 + n2 × m2) / (n1 + n2)`.

