INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00178', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 45, 'In a class, 28 students scored an average of 58 marks and the other 32 students scored an average of 78 marks. Find the combined average of the whole class.', 'The combined average is the total marks of all students divided by the total number of students: `(n1 × m1 + n2 × m2) / (n1 + n2)`.

`(28 × 58 + 32 × 78) / (28 + 32) = 4120 / 60 = 68.67`.

The answer is **68.67**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00179', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 46, 'A sum of ₹4800 is divided among three people in the ratio 3:5:8. Find the difference between the largest and smallest shares.', 'Each share equals `Total × (part / sum of parts)`, where the sum of parts is `3+5+8 = 16`.

The largest share is `4800 × 8/16 = ₹2400` and the smallest share is `4800 × 3/16 = ₹900`, giving a difference of `2400 - 900 = ₹1500`.

The answer is **₹1500**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00180', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 47, 'A sum of ₹6300 is divided among three people in the ratio 2:4:7. Find the difference between the largest and smallest shares.', 'Each share equals `Total × (part / sum of parts)`, where the sum of parts is `2+4+7 = 13`.

The largest share is `6300 × 7/13 = ₹3392.31` and the smallest share is `6300 × 2/13 = ₹969.23`, giving a difference of `3392.31 - 969.23 = ₹2423.08`.

The answer is **₹2423.08**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00181', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 48, 'A sum of ₹5500 is divided among three people in the ratio 1:4:6. Find the difference between the largest and smallest shares.', 'Each share equals `Total × (part / sum of parts)`, where the sum of parts is `1+4+6 = 11`.

The largest share is `5500 × 6/11 = ₹3000` and the smallest share is `5500 × 1/11 = ₹500`, giving a difference of `3000 - 500 = ₹2500`.

