INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00182', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 49, 'A sum of ₹7200 is divided among three people in the ratio 3:4:5. Find the difference between the largest and smallest shares.', 'Each share equals `Total × (part / sum of parts)`, where the sum of parts is `3+4+5 = 12`.

The largest share is `7200 × 5/12 = ₹3000` and the smallest share is `7200 × 3/12 = ₹1800`, giving a difference of `3000 - 1800 = ₹1200`.

The answer is **₹1200**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00183', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 50, 'A sum of ₹4000 is divided among three people in the ratio 2:3:5. Find the difference between the largest and smallest shares.', 'Each share equals `Total × (part / sum of parts)`, where the sum of parts is `2+3+5 = 10`.

The largest share is `4000 × 5/10 = ₹2000` and the smallest share is `4000 × 2/10 = ₹800`, giving a difference of `2000 - 800 = ₹1200`.

