INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00184', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 51, 'Two varieties of rice costing ₹40/kg and ₹60/kg are mixed in the ratio 3:2. Find the average cost per kg of the mixture.', 'The average cost of a mixture is the weighted average: `(r1 × p1 + r2 × p2) / (r1 + r2)`.

`(3 × 40 + 2 × 60) / (3 + 2) = 240 / 5 = ₹48` per kg.

The answer is **₹48 per kg**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00185', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 52, 'Two varieties of rice costing ₹30/kg and ₹50/kg are mixed in the ratio 2:5. Find the average cost per kg of the mixture.', 'The average cost of a mixture is the weighted average: `(r1 × p1 + r2 × p2) / (r1 + r2)`.

