INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00186', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 53, 'Two varieties of rice costing ₹25/kg and ₹45/kg are mixed in the ratio 4:3. Find the average cost per kg of the mixture.', 'The average cost of a mixture is the weighted average: `(r1 × p1 + r2 × p2) / (r1 + r2)`.

