INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00187', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 54, 'Two varieties of rice costing ₹80/kg and ₹50/kg are mixed in the ratio 1:2. Find the average cost per kg of the mixture.', 'The average cost of a mixture is the weighted average: `(r1 × p1 + r2 × p2) / (r1 + r2)`.

