INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00188', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 55, 'Two varieties of rice costing ₹20/kg and ₹35/kg are mixed in the ratio 5:4. Find the average cost per kg of the mixture.', 'The average cost of a mixture is the weighted average: `(r1 × p1 + r2 × p2) / (r1 + r2)`.

`(5 × 20 + 4 × 35) / (5 + 4) = 240 / 9 = ₹26.67` per kg.

