INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00189', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 56, 'A mixture of 40 litres contains liquids A and B in the ratio 3:2. How much of liquid B must be added so that the new ratio of A to B becomes 1:1?', 'The quantity of A is `40 × 3/(3+2) = 24` litres and the quantity of B is `40 × 2/(3+2) = 16` litres. Since only B is added, A stays fixed.

For the new ratio, `24 / (16 + x) = 1/1`, so `x = 24 × 1/1 - 16 = 8` litres.

The answer is **8 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00190', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 57, 'A mixture of 60 litres contains liquids A and B in the ratio 5:3. How much of liquid B must be added so that the new ratio of A to B becomes 1:2?', 'The quantity of A is `60 × 5/(5+3) = 37.5` litres and the quantity of B is `60 × 3/(5+3) = 22.5` litres. Since only B is added, A stays fixed.

For the new ratio, `37.5 / (22.5 + x) = 1/2`, so `x = 37.5 × 2/1 - 22.5 = 52.5` litres.

The answer is **52.5 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00191', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 58, 'A mixture of 50 litres contains liquids A and B in the ratio 2:3. How much of liquid B must be added so that the new ratio of A to B becomes 1:2?', 'The quantity of A is `50 × 2/(2+3) = 20` litres and the quantity of B is `50 × 3/(2+3) = 30` litres. Since only B is added, A stays fixed.

For the new ratio, `20 / (30 + x) = 1/2`, so `x = 20 × 2/1 - 30 = 10` litres.

The answer is **10 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00192', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 59, 'A mixture of 80 litres contains liquids A and B in the ratio 4:1. How much of liquid B must be added so that the new ratio of A to B becomes 2:3?', 'The quantity of A is `80 × 4/(4+1) = 64` litres and the quantity of B is `80 × 1/(4+1) = 16` litres. Since only B is added, A stays fixed.

For the new ratio, `64 / (16 + x) = 2/3`, so `x = 64 × 3/2 - 16 = 80` litres.

The answer is **80 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00193', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 60, 'A mixture of 45 litres contains liquids A and B in the ratio 3:1. How much of liquid B must be added so that the new ratio of A to B becomes 1:2?', 'The quantity of A is `45 × 3/(3+1) = 33.75` litres and the quantity of B is `45 × 1/(3+1) = 11.25` litres. Since only B is added, A stays fixed.

For the new ratio, `33.75 / (11.25 + x) = 1/2`, so `x = 33.75 × 2/1 - 11.25 = 56.25` litres.

The answer is **56.25 litres**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00194', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 61, 'Find the average of the first 20 odd natural numbers.', 'The first `n` odd natural numbers are `1, 3, 5, ..., (2n-1)`, and their sum is `n^2`.

The average is `n^2 / n = n`. Substituting `n = 20`, the average is `20`.

The answer is **20**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00195', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 62, 'Find the average of the first 15 even natural numbers.', 'The first `n` even natural numbers are `2, 4, 6, ..., 2n`, and their sum is `n(n+1)`.

The average is `n(n+1) / n = n+1`. Substituting `n = 15`, the average is `16`.

The answer is **16**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00196', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 63, 'Find the average of the first 30 odd natural numbers.', 'The first `n` odd natural numbers are `1, 3, 5, ..., (2n-1)`, and their sum is `n^2`.

