INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00197', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 64, 'Find the average of the first 25 even natural numbers.', 'The first `n` even natural numbers are `2, 4, 6, ..., 2n`, and their sum is `n(n+1)`.

