INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00198', 'math-aptitude-bank-2', 'Ratios, Averages & Mixtures', 2, 65, 'Find the average of the first 18 odd natural numbers.', 'The first `n` odd natural numbers are `1, 3, 5, ..., (2n-1)`, and their sum is `n^2`.

