INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00215', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 16, 'A man travels a certain distance at 40 km/h and returns the same distance at 60 km/h. Find his average speed for the entire journey.', 'When equal distances are covered at two different speeds, the average speed is the harmonic mean: `2 × s1 × s2 / (s1 + s2)`.

`2 × 40 × 60 / (40 + 60) = 4800 / 100 = 48` km/h.

The answer is **48 km/h**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00216', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 17, 'A man travels a certain distance at 50 km/h and returns the same distance at 75 km/h. Find his average speed for the entire journey.', 'When equal distances are covered at two different speeds, the average speed is the harmonic mean: `2 × s1 × s2 / (s1 + s2)`.

