INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00219', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 20, 'A man travels a certain distance at 45 km/h and returns the same distance at 60 km/h. Find his average speed for the entire journey.', 'When equal distances are covered at two different speeds, the average speed is the harmonic mean: `2 × s1 × s2 / (s1 + s2)`.

