INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00220', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 21, 'Two trains of lengths 100 m and 150 m run on parallel tracks in the same direction at 72 km/h and 54 km/h respectively. Find the time taken by the faster train to cross the slower one.', 'When moving in the same direction, the relative speed is the difference of their speeds, converted to m/s using `× 5/18`: `(72 - 54) × 5/18` m/s.

The relative speed is `5` m/s, and the total distance to be covered is the sum of the lengths, `100 + 150 = 250` m. So time `= 250 / 5 = 50` seconds.

The answer is **50 seconds**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00221', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 22, 'Two trains of lengths 120 m and 180 m run on parallel tracks in the same direction at 80 km/h and 56 km/h respectively. Find the time taken by the faster train to cross the slower one.', 'When moving in the same direction, the relative speed is the difference of their speeds, converted to m/s using `× 5/18`: `(80 - 56) × 5/18` m/s.

The relative speed is `6.67` m/s, and the total distance to be covered is the sum of the lengths, `120 + 180 = 300` m. So time `= 300 / 6.67 = 45` seconds.

The answer is **45 seconds**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00222', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 23, 'Two trains of lengths 150 m and 200 m run on parallel tracks in the same direction at 90 km/h and 60 km/h respectively. Find the time taken by the faster train to cross the slower one.', 'When moving in the same direction, the relative speed is the difference of their speeds, converted to m/s using `× 5/18`: `(90 - 60) × 5/18` m/s.

