INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00235', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 36, 'A boat has a speed of 12 km/h in still water, and the speed of the stream is 2 km/h. Find the time taken by the boat to travel 56 km downstream and the time to travel the same distance upstream.', 'Downstream speed is `boat speed + stream speed = 12 + 2 = 14` km/h, and upstream speed is `boat speed - stream speed = 12 - 2 = 10` km/h.

