INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00240', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 41, 'A boat''s downstream speed is 20 km/h and its upstream speed is 12 km/h. Find the speed of the boat in still water and the speed of the stream.', 'The boat''s speed in still water is the average of the downstream and upstream speeds: `(downstream + upstream) / 2`. The stream''s speed is half their difference: `(downstream - upstream) / 2`.

Boat speed `= (20 + 12) / 2 = 16` km/h, and stream speed `= (20 - 12) / 2 = 4` km/h.

The answer is **boat speed = 16 km/h, stream speed = 4 km/h**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00241', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 42, 'A boat''s downstream speed is 24 km/h and its upstream speed is 16 km/h. Find the speed of the boat in still water and the speed of the stream.', 'The boat''s speed in still water is the average of the downstream and upstream speeds: `(downstream + upstream) / 2`. The stream''s speed is half their difference: `(downstream - upstream) / 2`.

