INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00250', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 51, 'A can complete a work in 12 days and B can complete the same work in 18 days. In how many days will they complete the work together?', 'Working together, their combined one-day work is `1/a + 1/b`, so the time taken together is `1 / (1/a + 1/b) = ab/(a+b)`.

`(12 × 18) / (12 + 18) = 216 / 30 = 7.2` days.

The answer is **7.2 days**.', '2026-11-14T06:17:56.365Z');
