INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00255', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 56, 'A is 2 times as efficient as B. Working together, they complete a piece of work in 12 days. In how many days can A alone, and B alone, complete the work?', 'If B alone takes `b` days, A alone takes `b/2` days (since A is 2 times as efficient). Their combined one-day work is `2/b + 1/b = (2+1)/b`, which equals `1/12`.

So `b = 12 × (2+1) = 36` days for B, and A takes `36/2 = 18` days.

The answer is **A takes 18 days, B takes 36 days**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00256', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 57, 'A is 3 times as efficient as B. Working together, they complete a piece of work in 15 days. In how many days can A alone, and B alone, complete the work?', 'If B alone takes `b` days, A alone takes `b/3` days (since A is 3 times as efficient). Their combined one-day work is `3/b + 1/b = (3+1)/b`, which equals `1/15`.

So `b = 15 × (3+1) = 60` days for B, and A takes `60/3 = 20` days.

