INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00257', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 58, 'A is 1.5 times as efficient as B. Working together, they complete a piece of work in 10 days. In how many days can A alone, and B alone, complete the work?', 'If B alone takes `b` days, A alone takes `b/1.5` days (since A is 1.5 times as efficient). Their combined one-day work is `1.5/b + 1/b = (1.5+1)/b`, which equals `1/10`.

