INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00259', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 60, 'A is 2.5 times as efficient as B. Working together, they complete a piece of work in 14 days. In how many days can A alone, and B alone, complete the work?', 'If B alone takes `b` days, A alone takes `b/2.5` days (since A is 2.5 times as efficient). Their combined one-day work is `2.5/b + 1/b = (2.5+1)/b`, which equals `1/14`.

So `b = 14 × (2.5+1) = 49` days for B, and A takes `49/2.5 = 19.6` days.

The answer is **A takes 19.6 days, B takes 49 days**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00260', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 61, 'Pipe A can fill a tank in 6 hours, while pipe B can empty the full tank in 8 hours. If both pipes are opened together, in how many hours will the tank be filled?', 'The net rate of filling is `1/a - 1/b` (fill rate minus empty rate), so the time to fill is the reciprocal of this net rate.

Net rate `= 1/6 - 1/8 = 0.04` per hour, so time `= 1 / 0.04 = 24` hours.

The answer is **24 hours**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00261', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 62, 'Pipe A can fill a tank in 10 hours, while pipe B can empty the full tank in 15 hours. If both pipes are opened together, in how many hours will the tank be filled?', 'The net rate of filling is `1/a - 1/b` (fill rate minus empty rate), so the time to fill is the reciprocal of this net rate.

Net rate `= 1/10 - 1/15 = 0.03` per hour, so time `= 1 / 0.03 = 30` hours.

The answer is **30 hours**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00262', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 63, 'Pipe A can fill a tank in 8 hours, while pipe B can empty the full tank in 12 hours. If both pipes are opened together, in how many hours will the tank be filled?', 'The net rate of filling is `1/a - 1/b` (fill rate minus empty rate), so the time to fill is the reciprocal of this net rate.

