INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00264', 'math-aptitude-bank-2', 'Time, Speed, Distance & Work', 3, 65, 'Pipe A can fill a tank in 9 hours, while pipe B can empty the full tank in 18 hours. If both pipes are opened together, in how many hours will the tank be filled?', 'The net rate of filling is `1/a - 1/b` (fill rate minus empty rate), so the time to fill is the reciprocal of this net rate.

Net rate `= 1/9 - 1/18 = 0.06` per hour, so time `= 1 / 0.06 = 18` hours.

