INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00265', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 0, 'Solve for x: `5x + 12 = 2x + 30`.', 'Bring all the `x` terms to one side and constants to the other: `5x - 2x = 30 - 12`.

This gives `3x = 18`, so `x = 18 / 3 = 6`.

The answer is **x = 6**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00266', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 1, 'Solve for x: `7x + 9 = 3x + 33`.', 'Bring all the `x` terms to one side and constants to the other: `7x - 3x = 33 - 9`.

This gives `4x = 24`, so `x = 24 / 4 = 6`.

The answer is **x = 6**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00267', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 2, 'Solve for x: `4x + 15 = 1x + 30`.', 'Bring all the `x` terms to one side and constants to the other: `4x - 1x = 30 - 15`.

This gives `3x = 15`, so `x = 15 / 3 = 5`.

The answer is **x = 5**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00268', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 3, 'Solve for x: `6x + 8 = 2x + 28`.', 'Bring all the `x` terms to one side and constants to the other: `6x - 2x = 28 - 8`.

