INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00269', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 4, 'Solve for x: `9x + 10 = 4x + 40`.', 'Bring all the `x` terms to one side and constants to the other: `9x - 4x = 40 - 10`.

This gives `5x = 30`, so `x = 30 / 5 = 6`.

The answer is **x = 6**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00270', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 5, 'Solve for x: `8x + 14 = 3x + 34`.', 'Bring all the `x` terms to one side and constants to the other: `8x - 3x = 34 - 14`.

This gives `5x = 20`, so `x = 20 / 5 = 4`.

The answer is **x = 4**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00271', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 6, 'A father''s age is 5 times his son''s age. After 10 years, the father''s age will be 3 times the son''s age. Find their present ages.', 'Let the son''s present age be `s`, so the father''s present age is `5s`. After 10 years: `5s + 10 = 3(s + 10)`.

Expanding: `5s + 10 = 3s + 30`, so `s(5-3) = 30-10`, giving `s = 20 / 2 = 10`. The father''s age is `5 × 10 = 50`.

The answer is **son = 10 years, father = 50 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00272', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 7, 'A father''s age is 4 times his son''s age. After 6 years, the father''s age will be 2 times the son''s age. Find their present ages.', 'Let the son''s present age be `s`, so the father''s present age is `4s`. After 6 years: `4s + 6 = 2(s + 6)`.

Expanding: `4s + 6 = 2s + 12`, so `s(4-2) = 12-6`, giving `s = 6 / 2 = 3`. The father''s age is `4 × 3 = 12`.

The answer is **son = 3 years, father = 12 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00273', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 8, 'A father''s age is 6 times his son''s age. After 9 years, the father''s age will be 3 times the son''s age. Find their present ages.', 'Let the son''s present age be `s`, so the father''s present age is `6s`. After 9 years: `6s + 9 = 3(s + 9)`.

Expanding: `6s + 9 = 3s + 27`, so `s(6-3) = 27-9`, giving `s = 18 / 3 = 6`. The father''s age is `6 × 6 = 36`.

The answer is **son = 6 years, father = 36 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00274', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 9, 'A father''s age is 3 times his son''s age. After 5 years, the father''s age will be 2 times the son''s age. Find their present ages.', 'Let the son''s present age be `s`, so the father''s present age is `3s`. After 5 years: `3s + 5 = 2(s + 5)`.

Expanding: `3s + 5 = 2s + 10`, so `s(3-2) = 10-5`, giving `s = 5 / 1 = 5`. The father''s age is `3 × 5 = 15`.

The answer is **son = 5 years, father = 15 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00275', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 10, 'A father''s age is 7 times his son''s age. After 6 years, the father''s age will be 4 times the son''s age. Find their present ages.', 'Let the son''s present age be `s`, so the father''s present age is `7s`. After 6 years: `7s + 6 = 4(s + 6)`.

Expanding: `7s + 6 = 4s + 24`, so `s(7-4) = 24-6`, giving `s = 18 / 3 = 6`. The father''s age is `7 × 6 = 42`.

The answer is **son = 6 years, father = 42 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00276', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 11, 'Solve the quadratic equation: `x^2 - 5x + 6 = 0`.', 'Find two numbers whose sum is 5 and whose product is 6; these are the roots since the equation can be factored as `(x - r1)(x - r2) = 0`.

The roots are `x = 3` and `x = 2`, since `3 + 2 = 5` and `3 × 2 = 6`.

The answer is **x = 3 or x = 2**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00277', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 12, 'Solve the quadratic equation: `x^2 - 7x + 10 = 0`.', 'Find two numbers whose sum is 7 and whose product is 10; these are the roots since the equation can be factored as `(x - r1)(x - r2) = 0`.

The roots are `x = 5` and `x = 2`, since `5 + 2 = 7` and `5 × 2 = 10`.

The answer is **x = 5 or x = 2**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00278', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 13, 'Solve the quadratic equation: `x^2 - 9x + 20 = 0`.', 'Find two numbers whose sum is 9 and whose product is 20; these are the roots since the equation can be factored as `(x - r1)(x - r2) = 0`.

The roots are `x = 5` and `x = 4`, since `5 + 4 = 9` and `5 × 4 = 20`.

The answer is **x = 5 or x = 4**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00279', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 14, 'Solve the quadratic equation: `x^2 - 11x + 30 = 0`.', 'Find two numbers whose sum is 11 and whose product is 30; these are the roots since the equation can be factored as `(x - r1)(x - r2) = 0`.

The roots are `x = 6` and `x = 5`, since `6 + 5 = 11` and `6 × 5 = 30`.

The answer is **x = 6 or x = 5**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00280', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 15, 'Solve the quadratic equation: `x^2 - 8x + 15 = 0`.', 'Find two numbers whose sum is 8 and whose product is 15; these are the roots since the equation can be factored as `(x - r1)(x - r2) = 0`.

The roots are `x = 5` and `x = 3`, since `5 + 3 = 8` and `5 × 3 = 15`.

The answer is **x = 5 or x = 3**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00281', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 16, 'For the quadratic equation `2x^2 + (-7)x + 3 = 0`, find the sum and product of its roots.', 'For a quadratic `ax^2+bx+c=0`, the sum of roots is `-b/a` and the product of roots is `c/a`.

Sum `= -(-7)/2 = 3.5`, and product `= 3/2 = 1.5`.

The answer is **sum = 3.5, product = 1.5**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00282', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 17, 'For the quadratic equation `3x^2 + (-11)x + 6 = 0`, find the sum and product of its roots.', 'For a quadratic `ax^2+bx+c=0`, the sum of roots is `-b/a` and the product of roots is `c/a`.

Sum `= -(-11)/3 = 3.67`, and product `= 6/3 = 2`.

The answer is **sum = 3.67, product = 2**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00283', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 18, 'For the quadratic equation `1x^2 + (-5)x + -6 = 0`, find the sum and product of its roots.', 'For a quadratic `ax^2+bx+c=0`, the sum of roots is `-b/a` and the product of roots is `c/a`.

Sum `= -(-5)/1 = 5`, and product `= -6/1 = -6`.

The answer is **sum = 5, product = -6**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00284', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 19, 'For the quadratic equation `4x^2 + (-12)x + 5 = 0`, find the sum and product of its roots.', 'For a quadratic `ax^2+bx+c=0`, the sum of roots is `-b/a` and the product of roots is `c/a`.

Sum `= -(-12)/4 = 3`, and product `= 5/4 = 1.25`.

The answer is **sum = 3, product = 1.25**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00285', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 20, 'For the quadratic equation `2x^2 + (-9)x + 4 = 0`, find the sum and product of its roots.', 'For a quadratic `ax^2+bx+c=0`, the sum of roots is `-b/a` and the product of roots is `c/a`.

Sum `= -(-9)/2 = 4.5`, and product `= 4/2 = 2`.

The answer is **sum = 4.5, product = 2**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00286', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 21, 'Solve the simultaneous equations: `2x + 3y = 17` and `1x + -1y = 1`.', 'Using elimination or substitution, solve the two linear equations for `x` and `y`.

Solving `2x + 3y = 17` and `1x + -1y = 1` simultaneously gives `x = 4` and `y = 3`.

The answer is **x = 4, y = 3**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00287', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 22, 'Solve the simultaneous equations: `3x + 2y = 19` and `1x + +1y = 7`.', 'Using elimination or substitution, solve the two linear equations for `x` and `y`.

Solving `3x + 2y = 19` and `1x + 1y = 7` simultaneously gives `x = 5` and `y = 2`.

The answer is **x = 5, y = 2**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00288', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 23, 'Solve the simultaneous equations: `4x + 1y = 16` and `2x + -1y = 2`.', 'Using elimination or substitution, solve the two linear equations for `x` and `y`.

