INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00311', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 46, 'Find the distance between the points (1, 2) and (4, 6).', 'The distance between two points `(x1,y1)` and `(x2,y2)` is given by `√[(x2-x1)^2 + (y2-y1)^2]`.

