INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00316', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 51, 'Find the midpoint of the line segment joining the points (2, 3) and (8, 7).', 'The midpoint of `(x1,y1)` and `(x2,y2)` is given by `((x1+x2)/2, (y1+y2)/2)`.

