INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00321', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 56, 'Two triangles are similar. A side of the larger triangle measures 12 cm and the corresponding side of the smaller triangle measures 8 cm. Find the ratio of their areas.', 'For similar triangles, the ratio of areas equals the square of the ratio of corresponding sides.

The side ratio is `8:12`, so the area ratio is `8^2 : 12^2 = 64:144`, which simplifies to `4:9`.

The answer is **4:9**.', '2026-11-14T06:17:56.365Z');
