INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00326', 'math-aptitude-bank-2', 'Algebra & Geometry', 4, 61, 'Find the sum of the interior angles of a regular polygon with 5 sides, and the measure of each interior angle.', 'The sum of the interior angles of an `n`-sided polygon is `(n-2) × 180°`, and for a regular polygon each angle is this sum divided by `n`.

Sum `= (5-2) × 180 = 540°`, and each interior angle `= 540/5 = 108°`.

The answer is **sum = 540°, each angle = 108°**.', '2026-11-14T06:17:56.365Z');
