INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00397', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 0, 'In a right triangle, the side opposite to angle A measures 3 cm, the side adjacent to angle A measures 4 cm, and the hypotenuse measures 5 cm. Find sin A, cos A, and tan A.', 'By definition, `sin A = opposite/hypotenuse`, `cos A = adjacent/hypotenuse`, and `tan A = opposite/adjacent`.

Substituting the given sides: `sin A = 3/5 = 3/5`, `cos A = 4/5 = 4/5`, `tan A = 3/4 = 3/4`.

The answer is **sin A = 3/5, cos A = 4/5, tan A = 3/4**.', '2026-11-14T06:17:56.365Z');
