INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00405', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 8, 'From a point on the ground 20 m away from the base of a tower, the angle of elevation to the top of the tower is 30°. Find the height of the tower.', 'The height of the tower is given by `height = distance × tan(angle of elevation)`.

`height = 20 × tan(30°) = 20√3/3 ≈ 11.55` m.

The answer is **20√3/3 m (≈ 11.55 m)**.', '2026-11-14T06:17:56.365Z');
