INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00421', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 24, 'A tower has a height of 25.98 m (i.e. 15√3 m). From a point on the ground, the angle of elevation to the top is 30°, and from a point on the same line closer to the tower, the angle of elevation is 60°. Find the distance between the two points.', 'If the tower height is `h`, the distance from a point with elevation angle θ is `h / tanθ = h × cotθ`. The distance between the two points is the difference of these two distances.

With `h = 15√3` m: distance from the 30° point is `h × cot30° = h√3 × √3 = 45` m, and distance from the 60° point is `h × cot60° = h√3/√3 = 15` m.

The answer is **45 - 15 = 30 m**.', '2026-11-14T06:17:56.365Z');
