INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00429', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 32, 'Evaluate: `sin 30° × cos 60° + cos 30° × sin 60°`.', 'Use the standard trigonometric values for 30°, 45°, 60°, and 90°.

This is `sin(30°+60°) = sin 90° = 1` by the sine addition formula.

The answer is **1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00430', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 33, 'Evaluate: `cos 45° × cos 45° − sin 45° × sin 45°`.', 'Use the standard trigonometric values for 30°, 45°, 60°, and 90°.

