INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00445', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 48, 'The number of units sold by a store over five months was as follows — January: 320, February: 340, March: 360, April: 380, May: 400. Find the average monthly sales.', 'The average is the total of all the values divided by the number of values.

