INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mathx-q00453', 'math-aptitude-bank-2', 'Trigonometry & Data Interpretation', 6, 56, 'A company''s annual revenue rose from ₹400 crore to ₹460 crore over one year. Find the percentage increase in revenue.', 'Percentage increase is given by `(New - Old) / Old × 100`.

